// studium-drive: Studium workbooks → Google Slides decks in the teacher's Google Drive.
//
//   POST {action:"status"}             teacher   → {connected, email}
//   POST {action:"link", back}         teacher   → {url}  (Google's consent page; it comes back here as a GET)
//   GET  ?code&state                   Google    → stores the teacher's Drive permission, back to Studium #drive=ok
//   POST {action:"build"}              student   → rebuilds their own deck from their saved workbook pages
//   POST {action:"build", class_code}  teacher   → rebuilds every student's deck in that class
//
// Each student gets one deck, "<name> · Workbook", in "Studium Workbooks/<class>" in the teacher's Drive. The deck is
// A3 landscape like the workbook, one page per slide, each page a full-bleed image. Students never get access.
// The only Google permission asked for is drive.file: Studium can see and change the files it made, nothing else.
//
// Secrets (Edge Functions > Secrets): GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET. Optional STUDIUM_RETURN_URL.
// SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are already there on Supabase.


const SB = Deno.env.get("SUPABASE_URL")!;
const SR = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const GID = Deno.env.get("GOOGLE_CLIENT_ID") ?? "";
const GSEC = Deno.env.get("GOOGLE_CLIENT_SECRET") ?? "";
const SELF = SB + "/functions/v1/studium-drive";
const RETURN = Deno.env.get("STUDIUM_RETURN_URL") ?? "https://studium.nz/?full";
const BUCKET = "studium-workbooks";
const A3 = { w: 15120000, h: 10692000 };   // 420 × 297 mm in EMU
const PPTX = "application/vnd.openxmlformats-officedocument.presentationml.presentation";
// where "back" may point: the live site, Netlify previews, and a local dev server
const BACK_OK = /^(https:\/\/(www\.)?studium\.nz|https:\/\/[a-z0-9-]+\.netlify\.app|http:\/\/localhost(:\d+)?)(\/|$)/;

const CORS = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "authorization, apikey, content-type", "Access-Control-Allow-Methods": "POST, GET, OPTIONS" };
const json = (b: unknown, status = 200) => new Response(JSON.stringify(b), { status, headers: { ...CORS, "Content-Type": "application/json" } });

// ---------- Supabase, as the service role ----------
async function db(path: string, init: RequestInit & { prefer?: string } = {}) {
  const h: Record<string, string> = { apikey: SR, Authorization: "Bearer " + SR, "Content-Type": "application/json" };
  if (init.prefer) h.Prefer = init.prefer;
  const r = await fetch(SB + "/rest/v1/" + path, { ...init, headers: h });
  const t = await r.text();
  if (!r.ok) throw new Error("db " + r.status + " " + t.slice(0, 200));
  return t ? JSON.parse(t) : null;
}
const one = async (path: string) => ((await db(path)) ?? [])[0] ?? null;
async function whoIs(req: Request): Promise<{ id: string; email?: string } | null> {
  const auth = req.headers.get("Authorization") ?? "";
  if (!auth.startsWith("Bearer ")) return null;
  const r = await fetch(SB + "/auth/v1/user", { headers: { apikey: SR, Authorization: auth } });
  return r.ok ? await r.json() : null;
}

// ---------- Google ----------
async function googleToken(refresh: string): Promise<string> {
  const r = await fetch("https://oauth2.googleapis.com/token", { method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ client_id: GID, client_secret: GSEC, refresh_token: refresh, grant_type: "refresh_token" }) });
  const j = await r.json();
  if (!j.access_token) throw new Error("google-token " + (j.error ?? r.status));
  return j.access_token;
}
async function g(tok: string, url: string, init: RequestInit = {}) {
  const r = await fetch(url, { ...init, headers: { Authorization: "Bearer " + tok, "Content-Type": "application/json", ...(init.headers ?? {}) } });
  const t = await r.text();
  if (!r.ok) { const e = new Error("google " + r.status + " " + t.slice(0, 300)); (e as any).status = r.status; throw e; }
  return t ? JSON.parse(t) : null;
}
async function alive(tok: string, id: string | null | undefined) {
  if (!id) return false;
  try { const f = await g(tok, `https://www.googleapis.com/drive/v3/files/${id}?fields=id,trashed`); return !f.trashed; }
  catch (e) { if ((e as any).status === 404 || (e as any).status === 403) return false; throw e; }
}
async function folder(tok: string, name: string, parent?: string) {
  const f = await g(tok, "https://www.googleapis.com/drive/v3/files?fields=id", { method: "POST",
    body: JSON.stringify({ name, mimeType: "application/vnd.google-apps.folder", ...(parent ? { parents: [parent] } : {}) }) });
  return f.id as string;
}
// a new A3 deck: the blank A3 PowerPoint, converted by Drive (the Slides API can't set a page size itself)
async function newDeck(tok: string, name: string, parent: string) {
  const bytes = Uint8Array.from(atob(A3_PPTX_B64), (c) => c.charCodeAt(0));
  const B = "studium" + crypto.randomUUID().replace(/-/g, "");
  const meta = JSON.stringify({ name, parents: [parent], mimeType: "application/vnd.google-apps.presentation" });
  const body = new Blob([`--${B}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${meta}\r\n--${B}\r\nContent-Type: ${PPTX}\r\n\r\n`, bytes, `\r\n--${B}--`]);
  const f = await g(tok, "https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id", { method: "POST", body, headers: { "Content-Type": `multipart/related; boundary=${B}` } });
  return f.id as string;
}

async function sha(s: string) {
  const h = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return Array.from(new Uint8Array(h)).map((x) => x.toString(16).padStart(2, "0")).join("").slice(0, 32);
}

// ---------- one student's deck ----------
type Result = { ok: boolean; reason?: string; skipped?: boolean; pages?: number };
async function buildFor(userId: string, force = false): Promise<Result> {
  const wb = await one(`studium_workbooks?user_id=eq.${userId}&select=pages,class_code,student`);
  if (!wb || !wb.class_code) return { ok: false, reason: "no-workbook" };
  const cls = await one(`studium_classes?code=eq.${encodeURIComponent(wb.class_code)}&select=code,name,teacher_id`);
  if (!cls) return { ok: false, reason: "no-class" };
  const tg = await one(`studium_teacher_google?teacher_id=eq.${cls.teacher_id}&select=*`);
  if (!tg) return { ok: false, reason: "not-connected" };
  const pages: { id: string; path: string; hash: string }[] = wb.pages ?? [];
  const name = `${wb.student || "Student"} · Workbook`;
  const hash = await sha(name + "|" + pages.map((p) => p.id + ":" + p.hash).join(","));
  const deckRow = await one(`studium_decks?user_id=eq.${userId}&select=*`);
  const tok = await googleToken(tg.refresh_token);
  if (!force && deckRow && deckRow.built_hash === hash && await alive(tok, deckRow.deck_id)) return { ok: true, skipped: true, pages: pages.length };

  // folders: Studium Workbooks / <class name>
  let root = tg.root_folder as string | null;
  if (!await alive(tok, root)) {
    root = await folder(tok, "Studium Workbooks");
    await db(`studium_teacher_google?teacher_id=eq.${cls.teacher_id}`, { method: "PATCH", body: JSON.stringify({ root_folder: root }) });
  }
  const cf = await one(`studium_class_folders?class_code=eq.${encodeURIComponent(cls.code)}&select=folder_id`);
  let classFolder = cf?.folder_id as string | null;
  if (!await alive(tok, classFolder)) {
    classFolder = await folder(tok, cls.name || cls.code, root!);
    await db("studium_class_folders?on_conflict=class_code", { method: "POST", prefer: "resolution=merge-duplicates", body: JSON.stringify({ class_code: cls.code, folder_id: classFolder }) });
  } else await g(tok, `https://www.googleapis.com/drive/v3/files/${classFolder}?fields=id`, { method: "PATCH", body: JSON.stringify({ name: cls.name || cls.code }) });

  let deck = deckRow?.deck_id as string | null;
  if (!await alive(tok, deck)) deck = await newDeck(tok, name, classFolder!);
  else await g(tok, `https://www.googleapis.com/drive/v3/files/${deck}?fields=id`, { method: "PATCH", body: JSON.stringify({ name }) });

  // signed links Google fetches each page image from (15 minutes)
  let urls: string[] = [];
  if (pages.length) {
    const r = await fetch(`${SB}/storage/v1/object/sign/${BUCKET}`, { method: "POST", headers: { apikey: SR, Authorization: "Bearer " + SR, "Content-Type": "application/json" },
      body: JSON.stringify({ expiresIn: 900, paths: pages.map((p) => p.path) }) });
    const signed = await r.json();
    if (!r.ok) throw new Error("sign " + r.status);
    urls = signed.map((s: { signedURL: string }) => SB + "/storage/v1" + s.signedURL);
  }

  // rebuild: new slides first (on the blank layout the deck started with), then the old ones go
  const pres = await g(tok, `https://slides.googleapis.com/v1/presentations/${deck}?fields=slides(objectId,slideProperties(layoutObjectId)),layouts(objectId),pageSize`);
  const old: string[] = (pres.slides ?? []).map((s: { objectId: string }) => s.objectId);
  const layout = pres.slides?.[0]?.slideProperties?.layoutObjectId ?? pres.layouts?.[0]?.objectId;
  const W = pres.pageSize?.width?.magnitude ?? A3.w, H = pres.pageSize?.height?.magnitude ?? A3.h;
  const stamp = Date.now().toString(36), reqs: unknown[] = [];
  const slides = pages.length ? pages : [null];
  slides.forEach((_, i) => {
    const sid = `s${stamp}_${i}`;
    reqs.push({ createSlide: { objectId: sid, insertionIndex: i, ...(layout ? { slideLayoutReference: { layoutId: layout } } : {}) } });
    if (pages.length) reqs.push({ createImage: { objectId: `i${stamp}_${i}`, url: urls[i], elementProperties: { pageObjectId: sid,
      size: { width: { magnitude: W, unit: "EMU" }, height: { magnitude: H, unit: "EMU" } }, transform: { scaleX: 1, scaleY: 1, translateX: 0, translateY: 0, unit: "EMU" } } } });
    else {
      reqs.push({ createShape: { objectId: `t${stamp}`, shapeType: "TEXT_BOX", elementProperties: { pageObjectId: sid,
        size: { width: { magnitude: W * 0.8, unit: "EMU" }, height: { magnitude: 1200000, unit: "EMU" } }, transform: { scaleX: 1, scaleY: 1, translateX: W * 0.1, translateY: H * 0.42, unit: "EMU" } } } });
      reqs.push({ insertText: { objectId: `t${stamp}`, text: `${wb.student || "This student"} hasn't made any workbook pages yet.` } });
    }
  });
  old.forEach((id) => reqs.push({ deleteObject: { objectId: id } }));
  await g(tok, `https://slides.googleapis.com/v1/presentations/${deck}:batchUpdate`, { method: "POST", body: JSON.stringify({ requests: reqs }) });

  await db("studium_decks?on_conflict=user_id", { method: "POST", prefer: "resolution=merge-duplicates",
    body: JSON.stringify({ user_id: userId, deck_id: deck, built_hash: hash, built_at: new Date().toISOString() }) });
  return { ok: true, pages: pages.length };
}

// ---------- the request ----------
Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: CORS });
  const u = new URL(req.url);
  try {
    // Google coming back after "Connect Google Drive"
    if (req.method === "GET") {
      const state = u.searchParams.get("state") ?? "";
      const st = state ? await one(`studium_google_states?state=eq.${encodeURIComponent(state)}&select=*`) : null;
      if (st) await db(`studium_google_states?state=eq.${encodeURIComponent(state)}`, { method: "DELETE" });
      const back = st?.back && BACK_OK.test(st.back) ? st.back : RETURN;
      const go = (ok: boolean) => new Response(null, { status: 302, headers: { Location: back + "#drive=" + (ok ? "ok" : "error") } });
      const code = u.searchParams.get("code");
      if (!st || !code || Date.now() - Date.parse(st.created_at) > 15 * 60000) return go(false);
      const r = await fetch("https://oauth2.googleapis.com/token", { method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({ code, client_id: GID, client_secret: GSEC, redirect_uri: SELF, grant_type: "authorization_code" }) });
      const t = await r.json();
      if (!t.refresh_token) return go(false);
      let email = "";
      try { email = JSON.parse(atob(t.id_token.split(".")[1].replace(/-/g, "+").replace(/_/g, "/"))).email ?? ""; } catch { /* no email, still fine */ }
      const prev = await one(`studium_teacher_google?teacher_id=eq.${st.teacher_id}&select=email`);
      if (prev && prev.email !== email) {
        // a different Google account: its Drive has none of the old folders or decks, so start them again there
        const classes = (await db(`studium_classes?teacher_id=eq.${st.teacher_id}&select=code`)) ?? [];
        for (const c of classes) {
          await db(`studium_class_folders?class_code=eq.${encodeURIComponent(c.code)}`, { method: "DELETE" });
          const ms = (await db(`studium_members?class_code=eq.${encodeURIComponent(c.code)}&select=user_id`)) ?? [];
          if (ms.length) await db(`studium_decks?user_id=in.(${ms.map((m: { user_id: string }) => m.user_id).join(",")})`, { method: "DELETE" });
        }
      }
      await db("studium_teacher_google?on_conflict=teacher_id", { method: "POST", prefer: "resolution=merge-duplicates",
        body: JSON.stringify({ teacher_id: st.teacher_id, email, refresh_token: t.refresh_token, connected_at: new Date().toISOString(), ...(prev && prev.email !== email ? { root_folder: null } : {}) }) });
      return go(true);
    }

    const me = await whoIs(req);
    if (!me) return json({ ok: false, error: "sign-in" }, 401);
    const body = await req.json().catch(() => ({}));

    if (body.action === "status") {
      const tg = await one(`studium_teacher_google?teacher_id=eq.${me.id}&select=email`);
      return json({ ok: true, connected: !!tg, email: tg?.email ?? null });
    }

    if (body.action === "link") {
      if (!GID || !GSEC) return json({ ok: false, error: "no-google-client" });
      const state = crypto.randomUUID();
      const back = typeof body.back === "string" && BACK_OK.test(body.back) ? body.back : RETURN;
      await db("studium_google_states", { method: "POST", body: JSON.stringify({ state, teacher_id: me.id, back }) });
      await db(`studium_google_states?created_at=lt.${new Date(Date.now() - 86400000).toISOString()}`, { method: "DELETE" });   // tidy old ones
      const q = new URLSearchParams({ client_id: GID, redirect_uri: SELF, response_type: "code", access_type: "offline", prompt: "consent select_account",
        include_granted_scopes: "true", state, scope: "openid email https://www.googleapis.com/auth/drive.file" });
      return json({ ok: true, url: "https://accounts.google.com/o/oauth2/v2/auth?" + q });
    }

    if (body.action === "build") {
      if (!GID || !GSEC) return json({ ok: false, reason: "no-google-client" });
      if (body.class_code) {   // the teacher's "Update all now"
        const cls = await one(`studium_classes?code=eq.${encodeURIComponent(body.class_code)}&select=teacher_id`);
        if (!cls || cls.teacher_id !== me.id) return json({ ok: false, reason: "not-your-class" }, 403);
        if (!await one(`studium_teacher_google?teacher_id=eq.${me.id}&select=teacher_id`)) return json({ ok: false, reason: "not-connected" });
        const ms = (await db(`studium_members?class_code=eq.${encodeURIComponent(body.class_code)}&select=user_id`)) ?? [];
        let built = 0, skipped = 0, failed = 0;
        for (const m of ms) {
          try { const r = await buildFor(m.user_id); if (r.skipped) skipped++; else if (r.ok) built++; }
          catch (e) { failed++; console.error("build", m.user_id, e); }
        }
        return json({ ok: failed === 0 || built + skipped > 0, built, skipped, failed });
      }
      return json(await buildFor(me.id));
    }
    return json({ ok: false, error: "unknown action" }, 400);
  } catch (e) {
    console.error(e);
    return json({ ok: false, error: String((e as Error).message ?? e).slice(0, 300) }, 500);
  }
});

// A blank A3-landscape PowerPoint (one blank slide), made with python-pptx. Drive converts it into each new deck.
const A3_PPTX_B64 = "";
